cards=[]
c=compact('pei_siqing','裴思庆','裴思庆是唐代长安富有而强悍的商旅大豪，习惯把财富、武功和男性地位当作支配旁人的资格。他率驼队深入沙漠，能组织护卫击退盗伙，也以骑战和反手快刀重伤横行商道的匈奴大盗。他不是全无勇气的人，但这种勇气与残忍、自我开脱紧紧纠缠：为占有柔娘，他杀害结义兄弟荀十九，明知曾发毒誓，仍反复把暂时逃过灾难当成自己无罪的证明。沙暴使商队覆没，他在饥渴中失去一切，得到白衣女主救助后，却没有学会尊重救命者。在山腹中，他借侏儒翻译交代生平，又从对方临终话语知道被隐瞒的旧案已经曝光。侏儒顾念妹妹仍帮助他，他却把白衣女子急欲返回天国的愿望变成脱身机会，恶意编造刺心升天的解释，带走封存的金月亮。后世发现，他没有成功回到长安；具体死亡过程未被目击。更讽刺的是，恶意谎言恰好与异星装置的用途相合，女子的记忆得以留存，但这不改变他原本想害死她们的动机。他没有使誓言生效或免疫的神力，所有可怕之处来自可信的武技、洞察欲望和拒绝认错的性格。','早已死亡，未见确切死因；参战恢复离开山腹前后最后可自主行动的人类形态并保留终局事实',['主角','反派'],'维护自身尊严、占有欲和生存，不愿承认自己受道德约束','先显示豪气与见识，观察对方最急切的愿望','被逼入绝境会用暴力、谎言和他人的希望换取脱身','会把偶然幸存解释为自己有理；终局知识可使其不安，却不强行洗成悔罪者',[ab('商旅骑战与刀术','熟练策骑、组织驼队防御，以交锋后的翻身反手刀重创骑手','必须有坐骑和兵器；沙暴、饥渴和严重皮肤伤可使其濒死'),ab('欲望识别与欺骗','根据对方求归天国的愿望编造自己能解释的仪式，换取物资与离开机会','不是精神控制；谎言须被相信，偶然符合技术真相不代表掌握技术')],[ev('083',1552,1619,'骑战、匈奴大盗受创与追击'),ev('083',1995,2049,'旧案被侏儒揭穿'),ev('083',2120,2166,'恶意假解释与离开、当时终局未知'),ev('084',813,829,'后续确认死亡年代与完整生平记录')],profile='martial');cards.append(c)
c=compact('jin_yueliang','金月亮','金月亮是活动于沙漠的高个子女子，蜂蜜色长发、明亮大眼和自由的举止使裴思庆难以忘怀。她曾受匈奴大盗支配，在大盗受裴刀伤而死后，持匕首潜到裴的身边，已经占尽先手，却终于放下兵刃。她与裴相爱而不愿跟他回长安，宁肯保有熟悉的沙漠和自己的来去。白衣女子为追寻神秘匕首将她掳去，她拒绝透露去向，被封在透明介质中，身体沉睡般留过漫长岁月。勒曼医院利用保存的细胞复制身体，恢复旧日记忆并输入现代知识，使她以完整自我重新出现；这依赖医院的整套技术，不是她自身不死。她感谢为复生出资的酋长，却明确拒绝成为后宫女人，坚持感恩与爱情各是自己的决定。她与杜令相恋，仍会追问裴思庆的过去，敢以玩笑惹新恋人吃醋，也并非全盘理解杜令的异星科学。最后她学会指定装置的操作，选择和杜令以记忆方式远行，地球身体留在设备中。卡片以这段选择后的知识呈现她，既保有冒险和亲密中的主动，也承认离体航行需要他人及设备，不能把一个复制身体算成无限替身库存。','与杜令的记忆离开地球，身体留在山洞装置中；演绎采用最后地球可行动身体及终局认知，远行能力须依装置','主角','自由选择所爱的人、去处和生活，不把恩情当成他人所有权','坦率调侃、主动追问旧事，喜欢新奇但不装懂陌生科技','涉及自由和秘密会坚守自己的决定；可持匕首以近距离突袭自保','感情可以改变，感谢援助不等于服从安排；承认自己不了解的原理',[ab('沙漠行动与匕首突袭','熟悉沙漠路线、潜入营帐，能在极近距离先制熟练武者','先手取决于对手疏忽与距离；未见正面击败裴或超常力量'),ab('指定记忆转移操作','接受杜令教导，能够配合执行特定设备程序','必须有对应装置与合作操作员；不能随意夺取身体或独立跨星传送')],[ev('083',1643,1687,'外观、匕首先手及自主放下'),ev('083',2085,2100,'封存原因'),ev('083',2940,2985,'复生知识、拒绝酋长安排及恋情'),ev('084',838,919,'身体复制、所学操作与借体条件'),ev('084',3115,3150,'记忆远行和留下身体')],profile='investigator',extra={'appearance':{'description':'身量高，蜂蜜色鬈曲长发，眼大鼻高；复制体延续原先外貌。','portrayal':'笑容鲜明、说话大胆，以亲昵和揶揄表达自己的主意。'}});rate(c,[3,1,1,3,2,5],neg=(2,3,1),tier='并',reason='按自身行动和特定操作知识评级，不把医院复制、杜令精神技术或星际设备常驻化');cards.append(c)
c=compact('du_ling','杜令','杜令以勒曼医院俊秀年轻医生的身份出现，驾驶飞机接走被封存的金月亮，参与细胞复制与记忆恢复。他回答卫斯理的问题常带笑意，既愿意解释关键，又擅长把真正来意暂时藏在轻松谈话里。金月亮的自主选择令医院原定安排落空，他不能用技术取消她对爱情的意愿，反而和她相恋。杜令实际来自遥远星球，来地球寻找遗落的混血女子；他以记忆到来，刺激一名医生的脑活动，借医院设备按自己记得的生命密码制造地球身体。找到储存六十二名女子记忆的装置后，他将她们送回原星，完成任务。准备与金月亮同返时，他一度要求借卫斯理和白素的身体完成程序，不愿教会二人操作，被他们拆穿这种不信任后才让合作更透明。最后记忆离开，两个身体留在地球设备中，期待将来或可再来。他拥有强大的专业知识与特定脑活动影响手段，但不是随念塑造任何生命的神；复杂复制和远行依赖医院、仪器、数据与外部操作。人物的张力在于真诚感情、任务保密和对他人身体自主的轻忽同时存在，不能只写成友善的万能说明员。','完成寻人任务后与金月亮记忆返乡，地球身体保留；采用最后可自主行动的地球身体，远行必须另满足设备与操作条件',['主角','阶段性对立者'],'完成同族寻回任务并与金月亮共同生活，守住其文明的秘密','用笑话和半真半假的解释试探信任；遇到专业问题讲清实际步骤','先保密甚至提议影响他人脑活动，被指出侵犯自主后可协商','认为记忆延续比身体更根本，但必须面对地球人对身体控制的在意',[ab('生命密码及复制医学','了解遗传信息并借勒曼设备培养身体、恢复或输入记忆','依赖医疗设施、材料、过程与正确资料；不能凭空瞬造身体或确保人格服从'),ab('记忆形式影响脑活动','离体记忆曾持续刺激医生脑部，使其完成复制工作；拟短时借体操作设备','需要接入与持续作用，未证实无条件瞬间压制任何意志；不能以记忆直接按动按钮'),ab('记忆储存与星际转送','寻找并操作特定装置，发送储存记忆，完成自己与同伴的远行','须装置、接收条件、外部操作；地球身体留下，不是随身无限距离闪现')],[ev('083',2780,2844,'医院代表、飞行及带走金月亮'),ev('083',2875,2941,'培养身体和恢复知识'),ev('083',3197,3227,'任务及储魂装置'),ev('084',786,796,'六十二人已送回'),ev('084',838,939,'来地球方式、脑影响及借体伦理'),ev('084',3115,3150,'实际远行')],profile='expert');rate(c,[2,5,3,5,5,5],neg=(3,4,2),tier='凶',reason='生命和脑活动技术具局部特殊作用；高分依赖具体设施，不赋予全域生命或灵魂概念权柄',mastery='基本掌握');cards.append(c)
cards.append(compact('rouniang_brother','柔娘之兄（天国侏儒）','这个始终没有记下姓名的侏儒，曾在荀十九家中做家童，是柔娘的哥哥。失散后，他生活在沙漠山腹中，成了白衣女主的伴侣与翻译，看似只会为女主传话，实际上早学会了她们的语言，却隐瞒这项本领以保留一点不受监视的空间。他认出裴思庆与妹妹的关系，也从旧事和刀伤判断出荀十九之死并非意外；揭露这一点时，裴才知道对方并不是可以随意轻视的人。然而侏儒没有借机复仇。他想到妹妹不应失去丈夫，临死前仍把白衣女子的数目、不会衰老的观察、金月亮遭封存的过程和逃走办法告诉裴，希望换得裴善待柔娘。他的判断并非全知，长期同居也不能弄懂山洞设备的真正性质；为保妹妹而帮助一个凶手，更是带有旧时代依附关系的伦理矛盾。最后他病衰而死，无法阻止裴把建议变成恶毒骗局。卡片保留其谨慎、忍耐、语言学习与对亲人的偏重，不替他增加降术或隐身能力，也不将矮小的身体当作心智或人格的缺陷。让他在新环境中选择何时透露已听懂的秘密，比不断自述身世更能表现这个角色。','在山腹向裴交代秘密后死亡；恢复临终衰弱之前最后可自主行动的人类形态并保留终局记忆','主角','以有限处境保护妹妹，同时保留自己知道而别人不知道的秘密','先听懂再决定是否翻译，对有利害关系的人谨慎透露','亲人可能受害时会压下怨恨帮助仇人，也会直指其最不愿承认的事实','知识来自观察与推断；保护妹妹不代表替裴的罪行辩护',[ab('语言与隐秘观察','长期学会白衣女子语言而佯装不懂，结合旧识、创伤和行为推断往事','观察范围限于能接触的谈话和生活；不懂异星设备，无读心或预言能力')],[ev('083',1981,2049,'隐瞒语言、辨旧案和亲属身份'),ev('083',2058,2113,'群体观察、临终帮助与死亡')],profile='expert'))
cards.append(compact('desert_queen','天国女主','天国女主是沙漠中六十二名白衣女子的领袖，浅灰色眼睛会映出周围天光，身手敏捷，熟悉骑骆驼穿行荒漠。她发现濒死的裴思庆时给水、衣物和坐骑，救了一个本可能死在沙中的陌生人。进入山腹后，她安排疗养和问话，借侏儒翻译听取他的生平，却未能识破他最重要的罪行与自利解释。女主和族人长期相信自己属于天国，迫切希望解开神赐匕首的秘密，这种愿望使她既能施予援助，也会同意抓人、封存金月亮以寻找匕首。她不是纯粹救难神，也不只是受骗的傻子，而是被遗失的身份和漫长等待支配的首领。裴利用这种迫切，提出以刀刺心的恶意解释，她与同伴最终舍弃身体。后来杜令确认她们是异星人与地球人的混血后裔，记忆由上代准备的装置保存，终于被送回原星。卡片采用她最后地球可行动形态及终局认知；返乡后新身体的具体性能并无记录。长久不老不等于对武器免疫，设备保存也不等于她个人可随意复活或读取灵魂。','旧地球身体已死，记忆由杜令送回原星；以最后地球可行动形态演绎，不虚构返乡新身体性能',['主角','阶段性对立者'],'找到归属与返乡道路，维持族人的共同生存','以领袖姿态救助、问话和安排生活，急于了解与归乡相关的线索','遇到被认为关乎全族未来的秘密时可能强行扣留和迫问','对归属的信仰强烈，但终局知识使她知道仪式的结果来自具体储存机制',[ab('荒漠行动与群体协调','熟练骑行、救援、管理族人的问话及共同生活','依赖物资和参与者，不具有对部族成员的绝对精神控制'),ab('长期不老的混血生命','同伴长期观察其外貌不随岁月衰老，杜令后来说明混血来源','不老不是刀枪不入；记忆保存依赖上代装置，不能随地自发复活')],[ev('083',1265,1339,'救援、外观与骑行'),ev('083',1430,1540,'问话与族群关系'),ev('083',2058,2100,'不老观察及封存金月亮'),ev('083',3197,3227,'混血身份和储存机制'),ev('084',786,796,'记忆返乡')],profile='investigator'))
cards.append(compact('desert_white_women','天国白衣女子（女主之外的族人）','这组白衣女子与女主共同生活在沙漠山腹中，是六十二人族群中其余未具名的成员。原文能分辨的个体主要是轮流记录和发问的八名女子，不能为每人补造姓名、特长或性格。本卡因此记录群体共同可证的经历，演绎时选取一名成员，不把人数累加成个人力量。她们保有自己的语言与文字，细致记下裴思庆的生平，在他讲到藏匕首的巢穴时追问正确位置；这种记录能力并没有使她们自动识别所有谎言。她们会掳去男人，既好奇外界，又不把男性当作唯一生活目的。为取得归乡所需的匕首，她们抓走拒绝吐露秘密的金月亮，将她封存，这是一种明确的强制伤害。漫长不老的生活没有消除对来历的焦虑，她们最终相信裴的恶意解释，舍弃身体。杜令后来确认她们的混血身世，找到上代留下的记忆储存装置并送回原星，归乡因此成为具体技术结果而非信仰自动兑现。卡片保留共同的求知、排外和盼归矛盾，成员可以对同一证据有不同反应，但不能凭这种演绎自由新增原文未见的特殊能力。','地球身体已死、记忆返乡；以一名未具名族人最后地球形态演绎，人数与原星新身体性能均不叠加',['主角群体','阶段性对立者'],'弄清自己的来历并找到返乡办法','共同记录、比较谈话中的矛盾，对外界人的经历保持好奇','涉及神秘匕首会迫问并可能动用封存设备','集体信念不能代替证据；不把同伴的判断写成每名成员的独立全知',[ab('记录、语言与审问协作','通过文字记录、轮流提问和相互比对追索线索','不是自动读心或测谎；未具名成员不得各自获得全组的每种技术'),ab('既有封存装置','族群曾以特殊介质封存金月亮，使细胞长期留存','原理与便携性不明，只作为原地点设施；无证据能随身封印任意敌人')],[ev('083',1430,1540,'八名记录者及群体活动'),ev('083',1631,1635,'询问位置而非全知'),ev('083',2058,2100,'六十二人及封存事实'),ev('084',786,796,'已通过装置返乡')],profile='ordinary'))
cards.append(compact('jinmoon_sheikh','金月亮事件的阿拉伯酋长','这位未被完整记下姓名的酋长拥有石油产地与重要港口，体态肥大，财富和地位使周围人认真看待他每一次反常决定。他本来并非以学术热情收藏古物，却命汉烈米把拍卖的一整批珍宝全部买回，因为其中封存着令他迷恋的金月亮。他面对没有回应的身体产生深情幻想，希望寻找能够使她活过来的办法；这种愿望推动了考古、调查和医学合作，也暴露出他把理想伴侣当作可购买目标的一面。卫斯理与白素提出送往勒曼医院时，他舍不得离开，直到向阿潘特王子询问并得到可信担保，才同意运送。杜令离去时，他留在机场祈祷，对实际技术仍一无所知。真正恢复旧记忆的金月亮拒绝成为他的后宫女人，医院后来另造没有她过去记忆的复制体送来，他大为高兴，并增加对汉烈米考古的资助。他没有获得原金月亮的爱情，也未在场知晓复制伦理的全部内幕。卡片让他在愿望、信仰与交易中行动，不把一切花费写成慈善，更不把财富折算成身体战力或对别人思想的控制。','收到另一个复制体后继续资助考古；对主要金月亮自主离去和复制安排的完整知情程度不明','主角／阶段性对立者','使自己迷恋的形象成为可以陪伴自己的活人，寻求可信的保证','以巨额资源和地位促成事情，谈到金月亮时容易失去平常的精明','需要割舍眼前占有才能求得结果时会迟疑，听取自己信任之人的担保','愿为希望付出代价，但需要学会对方的意愿不能用购买代替',[ab('资源组织与委托','委托学者采购整批古物、安排运输并资助研究','依赖实际财富和关系；没有随身军力、复生术或直接控制思想的能力')],[ev('083',2399,2427,'身份、财富、委托与外观'),ev('083',2780,2844,'询问王子、允许运送及祈祷'),ev('083',2954,2977,'主要金月亮拒绝与另造安排'),ev('084',763,765,'收到另一复制体并资助考古')],profile='ordinary'))
cards.append(compact('xiongnu_bandit','旋风盗首（匈奴大盗）','这名未具姓名的沙漠盗首率领一支以旋风为号的盗伙，利用商队难以组织反应的短暂窗口反复抢掠。他穿戴金光闪闪，挥弯刀骑无鞍骆驼冲入商旅，先砍断货架，让部下用钩竿拖走货物，再回头寻找下一次机会。他的强处是熟悉地形、坐骑速度、群体配合与使被劫者失措的声势，绝不是因为外号就能操纵风。面对早有准备的裴思庆，他被快骆驼咬住追赶，原可继续逃走，却因为部下和商队都在观看，不能接受被视作胆怯的首领，转头正面交锋。裴在交刀后翻身反手砍中他的背部，盗首伏身抱住驼颈逃入隐蔽山缝，手下看见失败便散去。后来金月亮明确说他已经死亡，并曾试图为他报仇，但也说明大盗把她当作女奴，失去他后才开始体会自由。卡片保留其迅速判断猎物弱点、依靠威望统御和受面子反噬的行为，不因为金月亮一时的情感便洗去支配关系。神秘匕首曾在他手中，也没有证据表明他知道储存记忆或返星的功能。','被裴思庆刀伤后死亡；恢复最后可行动的盗首形态并保留死亡经过，不携带已转手的神秘匕首','反派','以快速抢掠维持利益和首领威望，支配身边的人','先试探商队防御，利用速度和声势夺货','当众受挑战时容易为维持威望转入不利的正面对抗','熟悉沙漠不等于能赢所有武者，部下的服从取决于局势和利益',[ab('驼骑抢掠与弯刀','快速穿入驼队砍断货架，配合钩竿拖货；知道隐蔽山缝逃路','需要坐骑、地形和盗伙合作；正面对抗更快刀手会失利，伤势可致死')],[ev('083',1552,1562,'盗伙方式与兵器'),ev('083',1585,1630,'面子驱动交战、受伤逃离'),ev('083',1684,1687,'死亡信息'),ev('083',2968,2969,'金月亮对其支配关系的回顾')],profile='martial'))
save(cards)
cover('083',[('卫斯理','wei_sili','主角','整理古案和复生调查'),('白素','bai_su','主角','推理与联络'),('裴思庆','pei_siqing','主角／反派','前史主要叙述者及谋害'),('金月亮','jin_yueliang','主角','古今经历与自主选择'),('杜令','du_ling','主角','复制及混血寻回任务'),('柔娘之兄','rouniang_brother','主角','翻译、揭案及救助'),('女主','desert_queen','主角／对立者','救裴及群体返乡'),('白衣女子','desert_white_women','主角群体／对立者','记录、封存及返乡'),('阿拉伯酋长','jinmoon_sheikh','主角／对立者','委托与复生愿望'),('匈奴大盗','xiongnu_bandit','反派','抢掠、支配金月亮及刀战'),('温宝裕','wen_baoyu','重要配角','整理与论证'),('胡说','hu_shuo','重要配角','研究文字与讨论'),('胡明','hu_ming','重要配角','介绍汉烈米'),('汉烈米','yuanzhenxia_hanliemi','重要配角','考古委托及陪同调查'),('苏耀西','yuanzhenxia_suyaoxi','重要配角','拍卖协助'),('陶启泉','tao_qiquan','重要配角','基金及拍卖支持'),('阿潘特王子','a_pante','重要配角','电话担保医院')],[('柔娘、荀十九','古案关键受害者，但仅一次前史中呈现家庭关系与被害，没有独立主角行动线'),('第二个金月亮复制体','无旧记忆的另一人格，制造与送达仅转述，没有独立可核行动或反派性；不能合并主卡'),('老向导、驼队护卫、拍卖职员','一次性工作角色及受灾群像'),('温先生','本书家庭建议，待跨书核实际行动；不是其他系列同姓人物')],['女主单卡与其余族人群卡分开，群卡不叠加人数。','裴的谎言偶然符合设备机制，不等于知晓技术或拥有因果报应权能。','原文2311起有早前电话片段重复，不当作第二次独立事件。'])
